"""Primary keys: UUID v7, generated by the application rather than by PostgreSQL.

PostgreSQL 16 and the Python 3.12 standard library have no UUID v7, hence
``uuid-utils``. A v7 id starts with its creation time in milliseconds, and
``uuid_utils`` keeps the ids of one process strictly increasing within a
millisecond, so that ordering by id is ordering by creation: "lowest id
first" in the sweeps means "oldest first", and the B-tree of each primary key
grows at its right edge instead of splitting pages at random.
"""

from uuid import UUID

from uuid_utils import compat


def new_id() -> UUID:
    """A fresh UUID v7, as the standard library's ``uuid.UUID``."""
    return compat.uuid7()
